create or replace function private.record_auth_activity(p_event text) returns void language plpgsql security definer set search_path = '' as $$ declare v_actor uuid := auth.uid(); v_count integer := 0; v_action text; begin if v_actor is null then raise exception 'Authentication required'; end if; if p_event not in ('login','logout') then raise exception 'Unsupported authentication event'; end if; if not exists(select 1 from public.profiles p where p.id=v_actor and p.is_active=true) then raise exception 'Active account required'; end if; v_action := 'auth.' || p_event; if private.is_platform_admin() then insert into public.audit_logs(actor_user_id,action,entity_type,entity_id,metadata) values(v_actor,v_action,'auth_session',auth.jwt()->>'session_id',jsonb_build_object('source','application','event',p_event)); return; end if; insert into public.audit_logs(school_id,actor_user_id,action,entity_type,entity_id,metadata) select sm.school_id,v_actor,v_action,'auth_session',auth.jwt()->>'session_id',jsonb_build_object('source','application','event',p_event) from public.school_memberships sm where sm.user_id=v_actor and sm.status='active'; get diagnostics v_count = row_count; if v_count=0 then insert into public.audit_logs(school_id,actor_user_id,action,entity_type,entity_id,metadata) select distinct g.school_id,v_actor,v_action,'auth_session',auth.jwt()->>'session_id',jsonb_build_object('source','application','event',p_event) from public.guardians g where g.user_id=v_actor; get diagnostics v_count = row_count; end if; if v_count=0 then insert into public.audit_logs(actor_user_id,action,entity_type,entity_id,metadata) values(v_actor,v_action,'auth_session',auth.jwt()->>'session_id',jsonb_build_object('source','application','event',p_event)); end if; end; $$; revoke all on function private.record_auth_activity(text) from public,anon,authenticated; create or replace function public.record_auth_activity(p_event text) returns void language sql security invoker set search_path = '' as $$ select private.record_auth_activity(p_event); $$; revoke all on function public.record_auth_activity(text) from public,anon; grant execute on function public.record_auth_activity(text) to authenticated;